CREATE OR REPLACE PROCEDURE sp(
    para_dribbling          NUMBER,
    para_player_fifa_api_id NUMBER,
    para_long_shots         NUMBER,
    para_sliding_tackle     NUMBER
) AS
    v_count NUMBER;
    v_id    NUMBER;
    CURSOR cur_match IS
        SELECT id
          FROM Player_Attributes
         WHERE dribbling = para_dribbling
           AND player_fifa_api_id = para_player_fifa_api_id
           FOR UPDATE;
    CURSOR cur_slide IS
        SELECT id
          FROM Player_Attributes
         WHERE sliding_tackle IS NULL OR sliding_tackle = 0
           FOR UPDATE;
BEGIN
    SELECT COUNT(*)
      INTO v_count
      FROM Player_Attributes
     WHERE dribbling = para_dribbling
       AND player_fifa_api_id = para_player_fifa_api_id;

    IF v_count > 0 THEN
        OPEN cur_match;
        LOOP
            FETCH cur_match INTO v_id;
            EXIT WHEN cur_match%NOTFOUND;
            UPDATE Player_Attributes
               SET long_shots = para_long_shots
             WHERE CURRENT OF cur_match;
        END LOOP;
        CLOSE cur_match;
    ELSE
        INSERT INTO Player_Attributes (dribbling, player_fifa_api_id, long_shots)
        VALUES (para_dribbling, para_player_fifa_api_id, para_long_shots);
    END IF;

    OPEN cur_slide;
    LOOP
        FETCH cur_slide INTO v_id;
        EXIT WHEN cur_slide%NOTFOUND;
        UPDATE Player_Attributes
           SET sliding_tackle = CASE
                                    WHEN long_shots IS NOT NULL AND long_shots <> 0 THEN long_shots
                                    ELSE para_sliding_tackle
                                END
         WHERE CURRENT OF cur_slide;
    END LOOP;
    CLOSE cur_slide;
END sp;

